def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves."""
    paths = set()

    def _diff(b, a, prefix):
        for key in b:
            path = f"{prefix}.{key}" if prefix else key
            if key not in a:
                paths.add(path)
            else:
                bv, av = b[key], a[key]
                if isinstance(bv, dict) and isinstance(av, dict):
                    _diff(bv, av, path)
                elif bv != av:
                    paths.add(path)

        for key in a:
            if key not in b:
                path = f"{prefix}.{key}" if prefix else key
                paths.add(path)

    _diff(before, after, "")
    return sorted(paths)
```

