def frames(lines):
    result = []
    data_fields = []
    for line in lines:
        if line == '':
            if data_fields:
                result.append('\n'.join(data_fields))
                data_fields = []
        elif line.startswith('<!--'):
            continue
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_fields.append(value)
        else:
            continue
    return result
