def unique_latest(records):
    best = {}
    order = []
    seen = set()

    for record in records:
        rid = record["id"]
        if rid not in seen:
            seen.add(rid)
            order.append(rid)
            best[rid] = record
        else:
            if record["timestamp"] >= best[rid]["timestamp"]:
                best[rid] = record

    return [best[rid] for rid in order]
