import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    - Overlay values replace base values (including lists and None).
    - A None value in overlay replaces the base value with None; it does not delete the key.
    - When both sides hold a dict at the same key, they are merged recursively.
    - The returned dict is deep-independent of both inputs.
    """
    result = {}

    for key, value in base.items():
        result[key] = copy.deepcopy(value)

    for key, value in overlay.items():
        if key in base and isinstance(base[key], dict) and isinstance(value, dict):
            result[key] = merge(base[key], value)
        else:
            result[key] = copy.deepcopy(value)

    return result
```

