def flatten(value):
    if not value:
        return {}
    result = {}
    for key, val in value.items():
        if isinstance(val, dict) and val:
            flat = flatten(val)
            for k, v in flat.items():
                result[f"{key}.{k}"] = v
        elif isinstance(val, dict):
            result[key] = {}
        else:
            result[key] = val
    return result
