def normalize(path):
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if not path.startswith('/'):
        raise ValueError("path must be absolute")

    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

