def pack(items, max_bytes):
    if not isinstance(max_bytes, int) or max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    byte_lengths = [len(s.encode("utf-8")) for s in items]

    for i, bl in enumerate(byte_lengths):
        if bl > max_bytes:
            raise ValueError(
                f"Item at index {i} has UTF-8 length {bl} exceeding max_bytes {max_bytes}"
            )

    if not items:
        return []

    result = []
    current_batch = []
    current_size = 0

    for i, item in enumerate(items):
        if current_size + byte_lengths[i] <= max_bytes:
            current_batch.append(item)
            current_size += byte_lengths[i]
        else:
            result.append(current_batch)
            current_batch = [item]
            current_size = byte_lengths[i]

    if current_batch:
        result.append(current_batch)

    return result
